// Identity comes from the channel: only this chat's orders are ever visible.
const t = $('When Executed by Another Workflow').first().json;
const chatId = String(t.chat_id ?? '');
const wanted = String(t.order_id ?? '').toUpperCase().trim();
const mine = $input.all().map(i => i.json)
  .filter(r => r.order_id && String(r.chat_id) === chatId)
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
const tidy = o => {
  let items;
  try { items = JSON.parse(o.items_json).map(l => ({ product: l.name, qty: l.qty, unit: l.unit })); } catch (e) { items = o.items_json; }
  return { order_id: o.order_id, items, total: Number(o.total), status: o.status, delivery_date: o.delivery_date,
           rider: o.rider || undefined, refunded: o.refunded || 'no' };
};
if (!chatId) return [{ json: { found: false, error: 'No customer identity' } }];
if (wanted) {
  const o = mine.find(r => String(r.order_id).toUpperCase() === wanted);
  // Same answer whether the order doesn't exist or belongs to someone else: nothing leaks.
  if (!o) return [{ json: { found: false, message: `No order ${wanted} on this customer's account.` } }];
  return [{ json: { found: true, ...tidy(o) } }];
}
if (!mine.length) return [{ json: { found: false, message: 'This customer has no orders yet.' } }];
return [{ json: { found: true, orders: mine.slice(0, 3).map(tidy) } }];
